<?php namespace App\Repositories\MySQL; use App\Database\MySQLConnection; use App\Repositories\Interfaces\AdminRepositoryInterface;
final class MySQLAdminRepository implements AdminRepositoryInterface { public function __construct(private MySQLConnection $db){} public function findByUsername(string $u):?array{$s=$this->db->pdo()->prepare('SELECT * FROM admins WHERE username=?');$s->execute([$u]);return $s->fetch()?:null;} public function save(string $u,string $h):string{$s=$this->db->pdo()->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$s->execute([$u,$h]);return (string)$this->db->pdo()->lastInsertId();} }
